package com.tnr.cityguide.user;
import com.tnr.cityguide.auth.*;import com.tnr.cityguide.storage.StorageService;
import java.util.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service
public class UserService {
 private final UserRepository users;private final StorageService storage;private final PasswordEncoder encoder;private final RefreshTokenRepository refresh;private final AuthService auth;
 public UserService(UserRepository users,StorageService storage,PasswordEncoder encoder,RefreshTokenRepository refresh,AuthService auth){this.users=users;this.storage=storage;this.encoder=encoder;this.refresh=refresh;this.auth=auth;}
 @Transactional(readOnly=true) public AuthDtos.UserDto get(UUID id){return dto(user(id));}
 @Transactional public AuthDtos.UserDto update(UUID id,PatchRequest r){User u=user(id);Map<String,String> errors=new LinkedHashMap<>();if(r.name()!=null){if(r.name().trim().length()<2)errors.put("name","Please enter your name.");else u.setName(r.name().trim());}if(r.phone()!=null){if(!r.phone().isEmpty()&&!r.phone().matches("^[+\\d][\\d\\s\\-()]{5,19}$"))errors.put("phone","Enter a valid phone number.");else u.setPhone(r.phone());}if(r.prefs()!=null){if(r.prefs().events()!=null)u.setNotifEvents(r.prefs().events());if(r.prefs().reviews()!=null)u.setNotifReviews(r.prefs().reviews());if(r.prefs().news()!=null)u.setNotifNews(r.prefs().news());}if(!errors.isEmpty())throw new FieldValidationException(errors);return dto(u);}
 @Transactional public AuthDtos.UserDto avatar(UUID id,MultipartFile file){User u=user(id);String path=storage.store("avatars",file,2L*1024*1024);storage.delete(u.getAvatarUrl());u.setAvatarUrl(path);return dto(u);}
 @Transactional public AuthDtos.UserDto removeAvatar(UUID id){User u=user(id);storage.delete(u.getAvatarUrl());u.setAvatarUrl(null);return dto(u);}
 @Transactional public AuthDtos.AuthResponse changePassword(UUID id,String current,String next,String confirm){User u=user(id);if(!encoder.matches(current==null?"":current,u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");List<String> missing=new ArrayList<>();String p=next==null?"":next;if(p.length()<8)missing.add("at least 8 characters");if(!p.matches(".*[A-Z].*"))missing.add("an uppercase letter");if(!p.matches(".*[a-z].*"))missing.add("a lowercase letter");if(!p.matches(".*\\d.*"))missing.add("a number");if(!missing.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"New password needs "+String.join(", ",missing)+".");if(!Objects.equals(next,confirm))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"New passwords do not match.");u.setPasswordHash(encoder.encode(next));refresh.revokeAll(id);return auth.issueFresh(id);}
 private User user(UUID id){return users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User no longer exists."));}
 private AuthDtos.UserDto dto(User u){return new AuthDtos.UserDto(u.getId(),u.getName(),u.getEmail(),u.getPhone(),u.getAvatarUrl(),u.getRole().name(),new AuthDtos.Prefs(u.isNotifEvents(),u.isNotifReviews(),u.isNotifNews()));}
 public record PatchRequest(String name,String phone,PrefsPatch prefs){} public record PrefsPatch(Boolean events,Boolean reviews,Boolean news){}
}
